// ── Helpers ───────────────────────────────────────────────────────────────────

function severityColor(severity: string): string {
  switch (severity.toLowerCase()) {
    case "critical": return "bg-red-500/20 text-red-400 border-red-500/40";
    case "high":     return "bg-orange-500/20 text-orange-400 border-orange-500/40";
    case "medium":   return "bg-blue-500/20 text-blue-400 border-blue-500/40";
    case "low":      return "bg-green-500/20 text-green-400 border-green-500/40";
    default:         return "bg-gray-500/20 text-gray-400 border-gray-500/40";
  }
}

function statusColor(status: string | null): string {
  if (!status) return "text-gray-500";
  if (status === "ok" || status === "success") return "text-green-400";
  if (status === "error" || status === "fail") return "text-red-400";
  return "text-yellow-400";
}

function fmtDate(iso: string | null | undefined): string {
  if (!iso) return "—";
  return new Date(iso).toLocaleString(undefined, {
    month: "short", day: "numeric", year: "numeric",
    hour: "2-digit", minute: "2-digit",
  });
}

async function invokeAdminUsers<T>(body: Record<string, unknown>): Promise<T> {
  const { data, error } = await supabase.functions.invoke("admin-users", { body });
  if (error) throw new Error(error.message);
  if (data && typeof data === "object" && "error" in data && data.error) {
    throw new Error(String(data.error));
  }
  return data as T;
}

