import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Activity, Shield, Zap, Bug, Server, Code, BarChart3, Brain,
  RefreshCw, AlertTriangle, CheckCircle2, Loader2, ChevronRight,
  Clock,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { getRuntimeConfig } from "@/lib/runtime-config";
import { supabase } from "@/integrations/supabase/client";

/* ── Types ────────────────────────────────────────────────────────────────── */

interface Finding {
  severity: "info" | "warning" | "critical";
  title:    string;
  detail?:  string;
  data?:    any;
  action?:  string;
}
interface AgentReport {
  agent:    string;
  status:   "ok" | "warning" | "critical";
  findings: Finding[];
  metric:   Record<string, any>;
  ran_ms:   number;
}
interface OpsResult {
  generated_at: string;
  latency_ms:   number;
  rollup: {
    overall_status: "ok" | "warning" | "critical";
    critical: number; warning: number; ok: number;
    total_findings: number;
  };
  agents: AgentReport[];
}

/* ── Helpers ──────────────────────────────────────────────────────────────── */

const AGENT_META: Record<string, { icon: any; description: string; gradient: string }> = {
  MonitoringAgent:          { icon: Activity,   description: "Function latency · error rate · dead-letter queue",      gradient: "from-cyan-500/20 to-blue-500/20" },
  SecurityAgent:            { icon: Shield,     description: "Auth failures · suspicious IPs · key hygiene",           gradient: "from-rose-500/20 to-orange-500/20" },
  PerformanceAgent:         { icon: Zap,        description: "Queue depth · stuck jobs · stale items · slow sources",  gradient: "from-amber-500/20 to-yellow-500/20" },
  BugFixAgent:              { icon: Bug,        description: "Repeated error patterns · failed jobs · root-cause hint",gradient: "from-red-500/20 to-rose-500/20" },
  InfrastructureAgent:      { icon: Server,     description: "Source health · pipeline freshness · auto-heal status",  gradient: "from-emerald-500/20 to-teal-500/20" },
  CodeReviewAgent:          { icon: Code,       description: "Static analysis hooks · ESLint · Trivy · gitleaks",      gradient: "from-violet-500/20 to-purple-500/20" },
  ProductIntelligenceAgent: { icon: BarChart3,  description: "User activity · case throughput · engagement trends",    gradient: "from-pink-500/20 to-fuchsia-500/20" },
  AIArchitectAgent:         { icon: Brain,      description: "Synthesises findings across agents · prioritisation",    gradient: "from-indigo-500/20 to-cyan-500/20" },
};

const SEV_STYLE: Record<string, string> = {
  critical: "bg-rose-500/15   text-rose-400   border-rose-500/40",
  warning:  "bg-amber-500/15  text-amber-400  border-amber-500/40",
  info:     "bg-cyan-500/15   text-cyan-400   border-cyan-500/40",
};
const STATUS_DOT: Record<string, string> = {
  ok:       "bg-emerald-400",
  warning:  "bg-amber-400",
  critical: "bg-rose-400 animate-pulse",
};

/* ── Component ────────────────────────────────────────────────────────────── */

export default function AutonomousOpsPanel() {
  const { toast } = useToast();
  const [running, setRunning] = useState(false);
  const [result, setResult]   = useState<OpsResult | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [activeAgent, setActiveAgent] = useState<string | null>(null);

  async function runOnce() {
    setRunning(true);
    try {
      const cfg = getRuntimeConfig();
      const r = await fetch(`${cfg.supabaseUrl}/functions/v1/auto-ops`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${cfg.supabasePublishableKey}`,
          "apikey":        cfg.supabasePublishableKey,
          "Content-Type":  "application/json",
        },
        body: JSON.stringify({}),
      });
      if (!r.ok) throw new Error(`auto-ops returned ${r.status}`);
      const data: OpsResult = await r.json();
      setResult(data);
      if (!activeAgent) setActiveAgent(data.agents[0]?.agent ?? null);
    } catch (e: any) {
      toast({ title: "Auto-Ops failed", description: e?.message ?? "Unknown error", variant: "destructive" });
    } finally {
      setRunning(false);
    }
  }

  // Initial load
  useEffect(() => { runOnce(); /* eslint-disable-next-line */ }, []);

  // Auto-refresh every 60s when toggle on
  useEffect(() => {
    if (!autoRefresh) return;
    const t = setInterval(runOnce, 60_000);
    return () => clearInterval(t);
  }, [autoRefresh]);

  // Load most-recent persisted findings as fallback if function 503s
  useEffect(() => {
    if (result || running) return;
    (async () => {
      const { data } = await supabase
        .from("ops_findings")
        .select("generated_at, latency_ms, overall_status, report, rollup")
        .order("generated_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (data) {
        setResult({
          generated_at: data.generated_at,
          latency_ms:   data.latency_ms ?? 0,
          rollup:       data.rollup as any,
          agents:       data.report   as any,
        });
        setActiveAgent((data.report as any)?.[0]?.agent ?? null);
      }
    })();
  }, [result, running]);

  const active = result?.agents.find((a) => a.agent === activeAgent) ?? result?.agents[0];

  return (
    <div className="space-y-4">
      {/* ── Header / controls ────────────────────────────────────────────── */}
      <Card className="bg-[#0a0f1e] border-white/10">
        <CardContent className="p-5 flex items-start justify-between flex-wrap gap-3">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <div className="w-9 h-9 rounded-xl bg-gradient-canva grid place-items-center shadow-canva">
                <Brain className="w-5 h-5 text-white" />
              </div>
              <div>
                <h3 className="text-base font-semibold text-foreground font-display">Autonomous Operations</h3>
                <p className="text-xs text-muted-foreground">8 inspector agents continuously sweep telemetry · tick now or auto-refresh every 60 s</p>
              </div>
            </div>
            {result && (
              <div className="mt-3 flex items-center gap-3 text-xs flex-wrap">
                <Badge className={`${
                  result.rollup.overall_status === "critical" ? SEV_STYLE.critical :
                  result.rollup.overall_status === "warning"  ? SEV_STYLE.warning  : "bg-emerald-500/15 text-emerald-400 border-emerald-500/40"
                }`}>
                  Overall: {result.rollup.overall_status}
                </Badge>
                <span className="text-muted-foreground">
                  <span className="text-rose-400">{result.rollup.critical}</span> critical ·
                  <span className="text-amber-400 ml-1">{result.rollup.warning}</span> warning ·
                  <span className="text-emerald-400 ml-1">{result.rollup.ok}</span> ok
                </span>
                <span className="text-muted-foreground">{result.rollup.total_findings} findings · {result.latency_ms}ms</span>
                <span className="text-muted-foreground flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  {new Date(result.generated_at).toLocaleTimeString()}
                </span>
              </div>
            )}
          </div>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={() => setAutoRefresh((v) => !v)} className="text-xs">
              <RefreshCw className={`w-3 h-3 mr-1.5 ${autoRefresh ? "animate-spin" : ""}`} />
              Auto-refresh: {autoRefresh ? "on" : "off"}
            </Button>
            <Button size="sm" onClick={runOnce} disabled={running} className="text-xs bg-gradient-violet-pink text-white shadow-canva">
              {running ? <Loader2 className="w-3 h-3 mr-1.5 animate-spin" /> : <Brain className="w-3 h-3 mr-1.5" />}
              {running ? "Running…" : "Run autonomous tick"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* ── Agent grid + detail ────────────────────────────────────────── */}
      {!result && running && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {Object.keys(AGENT_META).map((a) => (
            <Card key={a} className="bg-[#0a0f1e] border-white/10">
              <CardContent className="p-4 flex items-center gap-3">
                <Loader2 className="w-4 h-4 animate-spin text-cyan-400" />
                <span className="text-xs text-muted-foreground">{a.replace("Agent", "")}…</span>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {result && (
        <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
          {/* Agent list */}
          <div className="lg:col-span-2 space-y-2">
            {result.agents.map((a) => {
              const meta = AGENT_META[a.agent] ?? { icon: Activity, description: "", gradient: "" };
              const Icon = meta.icon;
              const isActive = activeAgent === a.agent;
              return (
                <Card
                  key={a.agent}
                  className={`bg-[#0a0f1e] cursor-pointer transition ${
                    isActive ? "border-cyan-500/60 shadow-cyber" : "border-white/10 hover:border-white/20"
                  }`}
                  onClick={() => setActiveAgent(a.agent)}
                >
                  <CardContent className="p-3.5 flex items-start gap-3">
                    <div className={`w-9 h-9 rounded-xl grid place-items-center bg-gradient-to-br ${meta.gradient} shrink-0`}>
                      <Icon className="w-4 h-4 text-white" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full ${STATUS_DOT[a.status]}`} />
                        <span className="text-sm font-semibold truncate">{a.agent.replace("Agent", "")}</span>
                        {a.findings.length > 0 && (
                          <Badge variant="outline" className="text-[10px] ml-auto">
                            {a.findings.length} finding{a.findings.length === 1 ? "" : "s"}
                          </Badge>
                        )}
                      </div>
                      <p className="text-[11px] text-muted-foreground mt-0.5 truncate">{meta.description}</p>
                      {a.findings[0] && (
                        <div className="mt-1.5 flex items-center gap-1.5 text-xs">
                          {a.findings[0].severity === "critical" ? <AlertTriangle className="w-3 h-3 text-rose-400 shrink-0" /> :
                           a.findings[0].severity === "warning"  ? <AlertTriangle className="w-3 h-3 text-amber-400 shrink-0" /> :
                                                                   <CheckCircle2 className="w-3 h-3 text-emerald-400 shrink-0" />}
                          <span className="truncate text-muted-foreground">{a.findings[0].title}</span>
                        </div>
                      )}
                    </div>
                    <ChevronRight className={`w-4 h-4 text-muted-foreground transition ${isActive ? "rotate-90" : ""}`} />
                  </CardContent>
                </Card>
              );
            })}
          </div>

          {/* Detail panel */}
          <div className="lg:col-span-3 space-y-3">
            {active && (
              <>
                <Card className="bg-[#0a0f1e] border-white/10">
                  <CardContent className="p-4 space-y-4">
                    <div className="flex items-center gap-3">
                      {(() => { const Icon = AGENT_META[active.agent]?.icon ?? Activity; return <Icon className="w-5 h-5 text-cyan-400" />; })()}
                      <div className="flex-1">
                        <h4 className="text-base font-semibold">{active.agent}</h4>
                        <p className="text-xs text-muted-foreground">{AGENT_META[active.agent]?.description}</p>
                      </div>
                      <Badge className={`${
                        active.status === "critical" ? SEV_STYLE.critical :
                        active.status === "warning"  ? SEV_STYLE.warning  : "bg-emerald-500/15 text-emerald-400 border-emerald-500/40"
                      }`}>{active.status}</Badge>
                      <Badge variant="outline" className="text-[10px]">{active.ran_ms}ms</Badge>
                    </div>

                    {/* Findings list */}
                    {active.findings.length === 0 ? (
                      <p className="text-xs text-muted-foreground">No findings — agent reports healthy.</p>
                    ) : (
                      <div className="space-y-2">
                        {active.findings.map((f, i) => (
                          <div key={i} className={`p-3 rounded-md border ${SEV_STYLE[f.severity]} bg-opacity-10`}>
                            <div className="flex items-start gap-2">
                              {f.severity === "critical" ? <AlertTriangle className="w-3.5 h-3.5 mt-0.5 shrink-0" /> :
                               f.severity === "warning"  ? <AlertTriangle className="w-3.5 h-3.5 mt-0.5 shrink-0" /> :
                                                           <CheckCircle2  className="w-3.5 h-3.5 mt-0.5 shrink-0" />}
                              <div className="flex-1 text-xs">
                                <div className="font-medium">{f.title}</div>
                                {f.detail && <div className="text-muted-foreground mt-0.5">{f.detail}</div>}
                                {f.action && <div className="text-foreground/80 mt-1">→ {f.action}</div>}
                                {f.data && (
                                  <pre className="text-[10px] text-muted-foreground mt-1 overflow-x-auto bg-black/20 p-1.5 rounded">
                                    {JSON.stringify(f.data, null, 2).slice(0, 600)}
                                  </pre>
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </CardContent>
                </Card>

                {/* Metrics */}
                {active.metric && Object.keys(active.metric).length > 0 && (
                  <Card className="bg-[#0a0f1e] border-white/10">
                    <CardContent className="p-4">
                      <div className="text-xs uppercase tracking-widest text-muted-foreground font-semibold mb-2">Live metrics</div>
                      <pre className="text-[11px] text-foreground/80 overflow-x-auto font-mono whitespace-pre-wrap">
                        {JSON.stringify(active.metric, null, 2).slice(0, 1800)}
                      </pre>
                    </CardContent>
                  </Card>
                )}
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
