import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  LineChart, Line, AreaChart, Area, Cell,
} from "recharts";
import { Activity, CheckCircle2, XCircle, Clock, TrendingUp, Zap } from "lucide-react";

interface MetricRow {
  function_name: string;
  duration_ms: number | null;
  items_processed: number;
  success: boolean;
  ts: string;
}

function useMetrics() {
  return useQuery({
    queryKey: ["function_metrics", "dashboard"],
    queryFn: async () => {
      const { data } = await supabase
        .from("function_metrics")
        .select("function_name, duration_ms, items_processed, success, ts")
        .order("ts", { ascending: false })
        .limit(500);
      return (data ?? []) as MetricRow[];
    },
    staleTime: 60_000,
    refetchInterval: 2 * 60_000,
  });
}

export function PipelineMetricsPanel() {
  const { data: metrics = [], isLoading } = useMetrics();

  if (isLoading) {
    return (
      <Card className="border-border/40">
        <CardContent className="pt-6 pb-4 text-center text-muted-foreground text-sm">
          Loading pipeline metrics…
        </CardContent>
      </Card>
    );
  }

  if (metrics.length === 0) {
    return (
      <Card className="border-border/40">
        <CardContent className="pt-6 pb-4 text-center text-muted-foreground text-sm">
          No metrics yet — pipeline fires after first queue run. Enable pg_cron in Supabase Dashboard.
        </CardContent>
      </Card>
    );
  }

  // Aggregate by function
  const byFn = new Map<string, { total: number; ok: number; avgMs: number; items: number; recent: string }>();
  for (const m of metrics) {
    const e = byFn.get(m.function_name) ?? { total: 0, ok: 0, avgMs: 0, items: 0, recent: m.ts };
    e.total++;
    if (m.success) e.ok++;
    e.avgMs = Math.round((e.avgMs * (e.total - 1) + (m.duration_ms ?? 0)) / e.total);
    e.items += m.items_processed;
    if (m.ts > e.recent) e.recent = m.ts;
    byFn.set(m.function_name, e);
  }

  const fnData = [...byFn.entries()]
    .map(([name, s]) => ({
      name: name.replace("fetch-", "").replace("-feeds", "-f").slice(0, 16),
      fullName: name,
      calls: s.total,
      successPct: Math.round(s.ok / s.total * 100),
      avgMs: s.avgMs,
      items: s.items,
    }))
    .sort((a, b) => b.calls - a.calls)
    .slice(0, 10);

  // Hourly throughput (last 12 hours)
  const now = Date.now();
  const hourlyData = Array.from({ length: 12 }, (_, i) => {
    const hourStart = now - (11 - i) * 3600000;
    const hourEnd   = hourStart + 3600000;
    const hourMetrics = metrics.filter(m => {
      const t = new Date(m.ts).getTime();
      return t >= hourStart && t < hourEnd;
    });
    const label = new Date(hourStart).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    return {
      hour: label,
      invocations: hourMetrics.length,
      items:       hourMetrics.reduce((s, m) => s + m.items_processed, 0),
      errors:      hourMetrics.filter(m => !m.success).length,
    };
  });

  // Summary stats
  const totalCalls  = metrics.length;
  const totalOk     = metrics.filter(m => m.success).length;
  const totalErrors = totalCalls - totalOk;
  const totalItems  = metrics.reduce((s, m) => s + m.items_processed, 0);
  const avgLatency  = Math.round(metrics.reduce((s, m) => s + (m.duration_ms ?? 0), 0) / totalCalls);
  const successPct  = Math.round(totalOk / totalCalls * 100);

  return (
    <div className="space-y-4">
      {/* Summary cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: "Total Invocations", value: totalCalls.toLocaleString(), icon: Activity, color: "text-cyan-400" },
          { label: "Success Rate",      value: `${successPct}%`,           icon: CheckCircle2, color: successPct >= 90 ? "text-emerald-400" : "text-orange-400" },
          { label: "Avg Latency",       value: `${avgLatency}ms`,          icon: Clock, color: "text-blue-400" },
          { label: "Items Processed",   value: totalItems.toLocaleString(), icon: TrendingUp, color: "text-purple-400" },
        ].map(({ label, value, icon: Icon, color }) => (
          <Card key={label} className="bg-card/60 border-border/40">
            <CardContent className="pt-4 pb-3 flex items-center gap-3">
              <Icon className={`h-4 w-4 ${color} shrink-0`} />
              <div>
                <div className="text-lg font-bold">{value}</div>
                <div className="text-[10px] text-muted-foreground">{label}</div>
              </div>
            </CardContent>
          </Card>
        ))}
        {totalErrors > 0 && (
          <Card className="bg-red-500/5 border-red-500/20 lg:hidden col-span-2">
            <CardContent className="pt-4 pb-3 flex items-center gap-3">
              <XCircle className="h-4 w-4 text-red-400 shrink-0" />
              <div>
                <div className="text-lg font-bold text-red-400">{totalErrors}</div>
                <div className="text-[10px] text-muted-foreground">Failed Invocations</div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Hourly throughput */}
        <Card className="border-border/40">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <Zap className="h-4 w-4 text-cyan-400" />
              Hourly Pipeline Throughput (last 12h)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={160}>
              <AreaChart data={hourlyData}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border) / 0.3)" />
                <XAxis dataKey="hour" tick={{ fontSize: 9 }} stroke="hsl(var(--muted-foreground))" />
                <YAxis tick={{ fontSize: 9 }} stroke="hsl(var(--muted-foreground))" />
                <Tooltip
                  contentStyle={{ background: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: 6, fontSize: 11 }}
                />
                <Area type="monotone" dataKey="items"       stroke="#22d3ee" fill="#22d3ee20" name="Items ingested" />
                <Area type="monotone" dataKey="invocations" stroke="#818cf8" fill="#818cf820" name="Invocations" />
                <Area type="monotone" dataKey="errors"      stroke="#f87171" fill="#f8717120" name="Errors" />
              </AreaChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Per-function success rates */}
        <Card className="border-border/40">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-emerald-400" />
              Function Success Rate (%)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={160}>
              <BarChart data={fnData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border) / 0.3)" />
                <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 9 }} stroke="hsl(var(--muted-foreground))" />
                <YAxis type="category" dataKey="name" tick={{ fontSize: 9 }} width={80} stroke="hsl(var(--muted-foreground))" />
                <Tooltip
                  contentStyle={{ background: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: 6, fontSize: 11 }}
                  formatter={(v) => [`${v}%`, "Success"]}
                />
                <Bar dataKey="successPct" radius={[0, 4, 4, 0]}>
                  {fnData.map((entry) => (
                    <Cell key={entry.fullName} fill={entry.successPct >= 90 ? "#34d399" : entry.successPct >= 70 ? "#fb923c" : "#f87171"} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      {/* Function detail table */}
      <Card className="border-border/40">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm">Function Performance Detail</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-1.5">
            {fnData.map(fn => (
              <div key={fn.fullName} className="flex items-center justify-between p-2 rounded bg-muted/20 text-xs">
                <span className="font-mono text-cyan-300 w-44 truncate">{fn.fullName}</span>
                <div className="flex gap-4 text-muted-foreground">
                  <span>{fn.calls} calls</span>
                  <Badge className={`text-[9px] px-1.5 ${fn.successPct >= 90 ? "bg-emerald-500/15 text-emerald-400" : fn.successPct >= 70 ? "bg-orange-500/15 text-orange-400" : "bg-red-500/15 text-red-400"}`}>
                    {fn.successPct}% ok
                  </Badge>
                  <span>{fn.avgMs}ms avg</span>
                  <span>{fn.items.toLocaleString()} items</span>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
